package command

import (
	"csghub-airgap/internal/infra/shell"
	"csghub-airgap/internal/infra/user"
	"csghub-airgap/internal/log"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/urfave/cli/v2"
)

const (
	// k3sUninstallScript is generated by the k3s install script; it only exists
	// on hosts where k3s was installed.
	k3sUninstallScript = "/usr/local/bin/k3s-uninstall.sh"
	// cleanupWaitSeconds is the countdown buffer before cleanup actually runs,
	// giving the operator a last chance to Ctrl+C after confirming.
	cleanupWaitSeconds = 10
)

func Cleanup() *cli.Command {
	return &cli.Command{
		Name:  "cleanup",
		Usage: "Cleanup k3s and all services",
		Flags: []cli.Flag{
			&cli.BoolFlag{
				Name:    "yes",
				Aliases: []string{"y"},
				Usage:   "Skip confirmation and run cleanup directly",
				Value:   false,
			},
		},
		Action: func(c *cli.Context) error {
			if err := user.EnsureRoot(); err != nil {
				return err
			}

			// Only proceed when k3s was actually installed on this host. The
			// uninstall script is created by the k3s installer, so a missing
			// script means there is nothing for us to clean up.
			if _, err := os.Stat(k3sUninstallScript); os.IsNotExist(err) {
				return fmt.Errorf("%s not found: k3s does not appear to be installed on this host", k3sUninstallScript)
			}

			// --yes is an explicit authorization (script-friendly): warn but do
			// not prompt or count down.
			if c.Bool("yes") {
				log.Warn("Cleanup will remove the entire k3s cluster and ALL its data on this host.")
			} else {
				printCleanupWarning()
				fmt.Print("Type 'yes' to continue: ")
				var input string
				if _, err := fmt.Scanln(&input); err != nil || !strings.EqualFold(strings.TrimSpace(input), "yes") {
					fmt.Println("Cleanup aborted.")
					return nil
				}

				// Countdown buffer so a hasty confirm can still be cancelled
				// with Ctrl+C before the destructive uninstall starts.
				fmt.Println()
				for i := cleanupWaitSeconds; i > 0; i-- {
					fmt.Printf("\rStarting cleanup in %2d seconds... (Ctrl+C to abort)", i)
					time.Sleep(time.Second)
				}
				fmt.Println("\rStarting cleanup now.                          ")
			}

			return shell.Execute(k3sUninstallScript)
		},
	}
}

// printCleanupWarning lists what cleanup removes. The uninstall script deletes
// the whole k3s cluster on this host (not just CSGHub resources), so the scope
// must be explicit before the operator confirms.
func printCleanupWarning() {
	fmt.Println()
	log.Warn("This will remove the entire k3s cluster on this machine and ALL its data:")
	fmt.Println("  - k3s service, systemd units, and /usr/local/bin/k3s binary")
	fmt.Println("  - /var/lib/rancher/k3s (cluster data, PVCs, Longhorn volumes)")
	fmt.Println("  - /var/lib/kubelet")
	fmt.Println("  - /etc/rancher/k3s, /run/k3s, /run/flannel")
	fmt.Println("  - Any k3s installed on this host, not only the CSGHub deployment")
	fmt.Println()
}
